<?php
declare(strict_types=1);
namespace CommunityHub;
final class Applications {
 public static function identity(array $q):bool{return $q['question_type']==='text'&&(bool)preg_match("/^(?:(?:what is|what's|enter|provide) (?:your )?|your )?discord user\s*name$/i",trim(preg_replace('/[?:*]+$/','',trim($q['label']))));}
 public static function questions(int $id,?array $u=null):array{$qs=App::rows('SELECT * FROM application_questions WHERE form_id=? ORDER BY sort_order,id',[$id]);foreach($qs as &$q)if($u&&self::identity($q)&&!empty($u['discord_username'])){$q['prefill_value']=$u['discord_username'];$q['account_identity']=true;}return $qs;}
 public static function game(string $action,array $u,array $d):array{if($action==='catalog')return ['ok'=>true,'forms'=>App::rows('SELECT id,title,slug,description FROM application_forms WHERE is_open=1 ORDER BY sort_order,title'),'history'=>App::rows('SELECT a.id,a.status,a.submitted_at,f.title FROM applications a JOIN application_forms f ON f.id=a.form_id WHERE a.user_id=? ORDER BY a.id DESC LIMIT 25',[$u['id']])];if($action==='form'){$f=App::row('SELECT * FROM application_forms WHERE id=? AND is_open=1',[App::id($d['form_id']??null)]);if(!$f)throw new HttpError('This application is closed or unavailable.',404);return ['ok'=>true,'form'=>$f,'questions'=>self::questions((int)$f['id'],$u)];}return self::submit($u,(string)($d['slug']??''),$d['answers']??[],true,$d['request_key']??null);}
 public static function submit(array $u,string $slug,array $answers,bool $tablet=false,?string $reference=null):array{App::membership($u);if($reference!==null&&!preg_match('/^[a-zA-Z0-9_-]{16,64}$/',$reference))throw new HttpError('Invalid submission reference.');return App::transaction(function()use($u,$slug,$answers,$tablet,$reference){$fresh=App::row('SELECT discord_id,discord_username,is_active FROM users WHERE id=? FOR UPDATE',[$u['id']]);if(empty($fresh['is_active'])||$fresh['discord_id']!==$u['discord_id'])throw new HttpError('Your account changed. Refresh and try again.',403);if($tablet&&!Domain::flag('applications'))throw new HttpError('In-game applications are disabled.',403);$f=App::row('SELECT * FROM application_forms WHERE slug=? AND is_open=1 FOR UPDATE',[$slug]);if(!$f)throw new HttpError('This application is closed or unavailable.',404);if($reference){$old=App::row('SELECT id,form_id FROM applications WHERE user_id=? AND submission_key=?',[$u['id'],$reference]);if($old){if($old['form_id']!=$f['id'])throw new HttpError('Submission reference belongs to another form.',409);return ['ok'=>true,'application_id'=>(int)$old['id']];}}if((int)$f['cooldown_days']>0&&App::row('SELECT id FROM applications WHERE user_id=? AND form_id=? AND submitted_at>DATE_SUB(NOW(),INTERVAL ? DAY) LIMIT 1',[$u['id'],$f['id'],(int)$f['cooldown_days']]))throw new HttpError('This application has a '.$f['cooldown_days'].' day submission cooldown.',409);$validated=[];foreach(self::questions((int)$f['id'],$fresh) as $q){$v=$answers['q_'.$q['id']]??'';$options=json_decode($q['options_json']??'[]',true)?:[];if(self::identity($q)){$v=$fresh['discord_username']??'';if(!$v)throw new HttpError('Reconnect your Discord account to fill your Discord username.',403);}if($q['question_type']==='checkbox'){$v=is_array($v)?$v:($v===''?[]:[$v]);foreach($v as $x)if(!is_string($x)||!in_array($x,$options,true))throw new HttpError('Choose valid options for '.$q['label']);$v=implode(', ',array_unique($v));}else{$v=App::text($v,$q['label'],10000,true);if($v&&in_array($q['question_type'],['radio','select'],true)&&!in_array($v,$options,true))throw new HttpError('Choose a valid option for '.$q['label']);if($v&&$q['question_type']==='number'&&!is_numeric($v))throw new HttpError('Enter a number for '.$q['label']);if($v&&$q['question_type']==='date'){if(!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$v,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))throw new HttpError('Enter a valid date for '.$q['label']);}if($v&&$q['question_type']==='url'&&(!filter_var($v,FILTER_VALIDATE_URL)||!in_array(parse_url($v,PHP_URL_SCHEME),['http','https'],true)))throw new HttpError('Enter a valid web address for '.$q['label']);}if($q['is_required']&&$v==='')throw new HttpError('Answer the required question: '.$q['label']);$validated[]=[(int)$q['id'],$v];}$id=App::insert("INSERT INTO applications(form_id,user_id,status,submitted_at,submission_key) VALUES(?,?,'submitted',NOW(),?)",[$f['id'],$u['id'],$reference]);foreach($validated as [$q,$v])App::query('INSERT INTO application_answers(application_id,question_id,answer_text) VALUES(?,?,?)',[$id,$q,$v]);App::query("INSERT INTO application_status_history(application_id,status,note,changed_by) VALUES(?,'submitted',?,?)",[$id,$tablet?'Application submitted in-game':'Application submitted',$u['id']]);Automation::emit('application_submitted',['entity_type'=>'application','entity_id'=>$id,'subject_user_id'=>(int)$u['id'],'application_id'=>$id,'form_id'=>(int)$f['id'],'form_slug'=>$slug,'form_title'=>$f['title'],'department_id'=>$f['department_id'],'status'=>'submitted'],(int)$u['id']);return ['ok'=>true,'application_id'=>$id];});}
}
